// Turns the single-file transcript page (web/vite.webview.config.ts →
// mobile/assets/tx/webview.html) into a TS module Capra imports as a string,
// so the WebView gets `source={{ html }}`: no file:// access rules, no asset
// plumbing, and it rides expo-updates like any other JS. Generated, ignored by
// git; root `postinstall` rebuilds it so npm ci on CI / EAS / blackstar has it.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const src = resolve(root, 'mobile/assets/tx/webview.html');
const out = resolve(root, 'mobile/src/tx-bundle.ts');

const html = readFileSync(src, 'utf8');
mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  `/* generated by \`npm run build:tx\` from web/src/webview — do not edit, do not commit */\n` +
    `export const TX_HTML = ${JSON.stringify(html)};\n` +
    `export const TX_BYTES = ${Buffer.byteLength(html)};\n`,
);
console.log(`tx-bundle: ${(Buffer.byteLength(html) / 1024).toFixed(0)} kB → mobile/src/tx-bundle.ts`);
